insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('queen-elizabeth-np-uganda', '05A', 'Queen Elizabeth National Park', 'Uganda', 'Tree-climbing lions, a hippo-thronged channel and 600 birds', 'live', 'verified', 'lion', 'Uganda — Queen Elizabeth / Rift Valley', '{"safari","adventure","ultra","deepdive"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["CONTENT-ONLY, no Book path, no waiver. DYNAMIC - re-verify each cycle, flip to live when it clears. Redirect safari demand to Kenya/Tanzania/Akagera","Uganda''s most popular savanna park (~1,978 km2, est. 1952 as Kazinga NP, renamed for Queen Elizabeth II): 95+ mammals and 600+ birds - the country''s most biodiverse safari","The tree-climbing lions of Ishasha (lions in fig/acacia trees - rare behaviour); the Kazinga Channel (40km, Lakes Edward<->George; UWA boat $30 - hippos/crocs/elephants/birds); Kyambura Gorge chimps (all latent while held)","Western edge borders Virunga (DR Congo) - a separate STANDING security concern even apart from the Ebola","Park fee $40 (24h); yellow fever MANDATORY for entry (all >=1yr, checked at Entebbe); eVisa (no visa-on-arrival); malaria in all regions (prophylaxis) - all latent while held","Live twins = Kenya (Maasai Mara/Amboseli), Tanzania (Serengeti), akagera-np-rwanda (Rwanda Big Five). Anchors the Uganda cluster with bwindi/murchison-falls/kibale"],"safety":{"emergency":"999 / 112","hospital":"Remote - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Kasese/Mbarara/Kampala (all latent while held)","malaria":"present in all regions - prophylaxis (latent while held)","yellow_fever":"MANDATORY for entry (all >=1yr, checked at Entebbe, >=10 days before)","ebola":"Sudan virus outbreak - PHEIC declared 2026-05-17 - the dominant, disqualifying hazard","drc_border":"western edge borders Virunga (DR Congo) - separate standing security concern; when live, keep to eastern/central sectors","activity_note":"HEALTH-SPINE DOMINANT: Ebola outbreak is the hazard. FCDO BASIS (gov.uk/foreign-travel-advice/uganda, read 2026-08-20): health screening on arrival and departure; Ugandan border with the DRC closed from 27 May per the National Task Force; the UK Returning Workers Scheme activated due to the outbreak. NOTE THE FCDO ADVISES AGAINST NO TRAVEL TO UGANDA - posture 1 - so any book-suppression here is OUR health judgement, not an advisory one, and is DAVID''S CALL - CONTENT-ONLY, Book suppressed, no waiver, redirect to Kenya/Tanzania/Akagera. DYNAMIC - re-verify each cycle. Safari/boat + malaria hazards + the DRC border are secondary/standing and moot for booking while held. When reopened: standard game-drive/boat rules, keep back from hippos/crocs, ranger-guided","booking_hold":false,"fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/uganda","read":"2026-08-20T14:48:47Z","page_updated":"2026-07-27T15:00:28+01:00","source_country":"uganda","quotes_note":"posture re-joined 2026-08-30 from handoff/fcdo-advisories/uganda.json, which was corrected 2026-08-23. The previous AREA-RESTRICTED was derived from prose about a NEIGHBOURING country.","posture_basis":"alert_status empty; quoted sentences name another country","posture_corrected":"2026-08-23 - was AREA-RESTRICTED, derived from prose about a neighbour"},"posture":"book-freely"},"timing":{"latent_peak":"Jun-Sep + Dec-Feb (drier - game at water, firmer tracks) - IF cleared","latent_green":"Mar-May + Oct-Nov (rains, lush/birdy, softer rates)","latent_booking_lead":"lodges 2-4 mo peak - NOT applicable while held","reverify_trigger":"check Uganda''s advisory EVERY publish cycle - DYNAMIC health advisory; re-verify western DRC/Virunga line before live routing","redirect":"live safari demand -> Kenya (Maasai Mara/Amboseli) / Tanzania (Serengeti) / akagera-np-rwanda (Rwanda Big Five)"},"jewels":[{"name":"The tree-climbing lions of Ishasha","si_tag":"safari","status":"held","tier":"premier","price_band":"HELD - no book path","timing":"HELD; latent Jun-Sep + Dec-Feb","dra